+fn controlled_increment_mod_2n_nested_2_3_4(
+    circ: &mut Circuit,
+    control: &QReg,
+    register: &[QReg],
+    dirty: &[QReg],
+    carry_a: &QReg,
+    carry_b: &QReg,
+) {
+    assert_q830_nested_counter_preconditions(control, register, dirty, carry_a, carry_b);
+    let dirty_refs = dirty.iter().collect::<Vec<_>>();
+    let a_controls = [control, &register[0], &register[1]];
+    mcx_dirty_ladder(circ, &a_controls, carry_a, &dirty_refs);
+    let b_controls = [carry_a, &register[2], &register[3], &register[4]];
+    mcx_dirty_ladder(circ, &b_controls, carry_b, &dirty_refs);
+    controlled_increment_mod_2n_dirty_ladder(circ, carry_b, &register[5..9], dirty);
+    mcx_dirty_ladder_reverse(circ, &b_controls, carry_b, &dirty_refs);
+    let middle_carry = [carry_b.borrowed_alias()];
+    controlled_increment_mod_2n_short_carry(circ, carry_a, &register[2..5], &middle_carry);
+    drop(middle_carry);
+    mcx_dirty_ladder_reverse(circ, &a_controls, carry_a, &dirty_refs);
+    controlled_increment_mod_2n_short_carry(circ, control, &register[..2], &[]);
+}
